CREATE TABLE billing_plans(id BINARY(16) PRIMARY KEY,code VARCHAR(255) NOT NULL UNIQUE,cycle VARCHAR(30) NOT NULL,usage_quota BIGINT NOT NULL,price DECIMAL(19,6) NOT NULL,currency CHAR(3) NOT NULL);
CREATE TABLE usage_records(id BINARY(16) PRIMARY KEY,idempotency_key VARCHAR(255) NOT NULL UNIQUE,client_id BINARY(16) NOT NULL,quantity BIGINT NOT NULL,occurred_at TIMESTAMP(6) NOT NULL);
CREATE TABLE invoices(id BINARY(16) PRIMARY KEY,invoice_number VARCHAR(255) NOT NULL UNIQUE,client_id BINARY(16) NOT NULL,cycle_from DATE NOT NULL,cycle_to DATE NOT NULL,total DECIMAL(19,6) NOT NULL,currency CHAR(3) NOT NULL,payment_status VARCHAR(30) NOT NULL,created_at TIMESTAMP(6) NOT NULL);
CREATE TABLE invoice_items(id BINARY(16) PRIMARY KEY,invoice_id BINARY(16) NOT NULL,description VARCHAR(255) NOT NULL,quantity BIGINT NOT NULL,unit_price DECIMAL(19,6) NOT NULL,amount DECIMAL(19,6) NOT NULL,FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE credit_notes(id BINARY(16) PRIMARY KEY,invoice_id BINARY(16) NOT NULL,amount DECIMAL(19,6) NOT NULL,reason VARCHAR(255) NOT NULL,created_at TIMESTAMP(6) NOT NULL,FOREIGN KEY(invoice_id) REFERENCES invoices(id));